1	export type Customer = { yearsWithMHPCO: number };
2	
3	export type Scenario = {
4	  customer: Customer;
5	  steps: Step[];
6	};
7	
8	export type Step =
9	  | { op: "quote"; items: Item[] }
10	  | { op: "claim"; policy: number; incident: Incident };
11	
12	export type Item = {
13	  type: string;
14	  material?: string;
15	  enchantment?: number;
16	  cursed?: boolean;
17	};
18	
19	export type Incident = {
20	  cause: string;
21	  damages: Damage[];
22	};
23	
24	export type Damage = {
25	  itemType: string;
26	  amount: number;
27	};
28	
29	export type Result = { premium: number } | { payout: number; remainingCap: number };
30	
31	const PROCESSING_FEE = 5;
32	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
33	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
34	  sword: 100,
35	  amulet: 60,
36	  staff: 80,
37	  potion: 40,
38	  rune: 25,
39	  moonstone: 25,
40	};
41	
42	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
43	
44	const BLOCK_SIZE = 3;
45	const BLOCK_BASE_PREMIUM = 60;
46	
47	const formsABuildingBlock = (alikeItems: Item[]): boolean =>
48	  alikeItems.length === BLOCK_SIZE;
49	
50	const sumOfBasePremiums = (items: Item[]): number =>
51	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
52	
53	const CURSE_SURCHARGE_RATE = 0.5;
54	const HIGH_ENCHANTMENT_LEVEL = 5;
55	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
56	
57	const isCursed = (item: Item): boolean => item.cursed === true;
58	
59	const isHighlyEnchanted = (item: Item): boolean =>
60	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
61	
62	// Every item-specific surcharge is a rate on THAT item's base premium, charged
63	// when its risk applies. Adding a new one means adding a row here — nothing else.
64	type ItemSurcharge = { appliesTo: (item: Item) => boolean; rate: number };
65	
66	const ITEM_SURCHARGES: ItemSurcharge[] = [
67	  { appliesTo: isCursed, rate: CURSE_SURCHARGE_RATE },
68	  { appliesTo: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
69	];
70	
71	const surchargeRateOn = (item: Item): number =>
72	  ITEM_SURCHARGES.reduce(
73	    (rate, surcharge) => (surcharge.appliesTo(item) ? rate + surcharge.rate : rate),
74	    0,
75	  );
76	
77	const itemSurchargesOn = (items: Item[]): number =>
78	  items.reduce((sum, item) => sum + basePremiumOf(item) * surchargeRateOn(item), 0);
79	
80	// Items of the same type are "alike"; each group is priced together so a
81	// building block can be recognised.
82	const alikeItemGroupsIn = (items: Item[]): Item[][] => [
83	  ...items
84	    .reduce(
85	      (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
86	      new Map<string, Item[]>(),
87	    )
88	    .values(),
89	];
90	
91	const basePremiumOfAlikeItems = (alikeItems: Item[]): number =>
92	  formsABuildingBlock(alikeItems) ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(alikeItems);
93	
94	const policyBaseOf = (items: Item[]): number =>
95	  alikeItemGroupsIn(items).reduce(
96	    (sum, alikeItems) => sum + basePremiumOfAlikeItems(alikeItems),
97	    0,
98	  );
99	
100	// Rounding always favours the MHPCO: premiums up, payouts down.
101	const premiumRoundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
102	
103	const LOYALTY_YEARS = 2;
104	const LOYALTY_DISCOUNT_RATE = -0.2;
105	
106	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = -0.15;
107	
108	// Each item in a quote is treated as a first insurance regardless of customer
109	// history, so this surcharge is unconditional.
110	const isAlwaysAFirstInsurance = (): boolean => true;
111	
112	const isLongStanding = ({ customer }: QuoteContext): boolean =>
113	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
114	
115	const isFollowUpContract = ({ precedingQuotes }: QuoteContext): boolean =>
116	  precedingQuotes > 0;
117	
118	// A quote is priced from the customer plus its place in the scenario's history.
119	type QuoteContext = { customer: Customer; precedingQuotes: number };
120	
121	// Every policy-wide modifier is a rate on the UNMODIFIED policy base — never on a
122	// base that already includes the item surcharges. Surcharges carry a positive
123	// rate, discounts a negative one. Adding a new one means adding a row here.
124	type PolicyModifier = { appliesTo: (context: QuoteContext) => boolean; rate: number };
125	
126	const POLICY_MODIFIERS: PolicyModifier[] = [
127	  { appliesTo: isAlwaysAFirstInsurance, rate: FIRST_INSURANCE_SURCHARGE_RATE },
128	  { appliesTo: isLongStanding, rate: LOYALTY_DISCOUNT_RATE },
129	  { appliesTo: isFollowUpContract, rate: FOLLOW_UP_CONTRACT_DISCOUNT_RATE },
130	];
131	
132	const policyModifierRateFor = (context: QuoteContext): number =>
133	  POLICY_MODIFIERS.reduce(
134	    (rate, modifier) => (modifier.appliesTo(context) ? rate + modifier.rate : rate),
135	    0,
136	  );
137	
138	const policyModifiersOn = (policyBase: number, context: QuoteContext): number =>
139	  policyBase * policyModifierRateFor(context);
140	
141	const quoteFor = (items: Item[], context: QuoteContext): Result => {
142	  const policyBase = policyBaseOf(items);
143	  const riskAdjustedBase = policyBase + itemSurchargesOn(items);
144	  return {
145	    premium: premiumRoundedInMHPCOsFavour(
146	      riskAdjustedBase + policyModifiersOn(policyBase, context) + PROCESSING_FEE,
147	    ),
148	  };
149	};
150	
151	export const runScenario = (scenario: Scenario): { results: Result[] } => {
152	  let precedingQuotes = 0;
153	  const results = scenario.steps.map((step) => {
154	    if (step.op !== "quote") throw new Error(`unsupported step: ${step.op}`);
155	    const result = quoteFor(step.items, {
156	      customer: scenario.customer,
157	      precedingQuotes,
158	    });
159	    precedingQuotes += 1;
160	    return result;
161	  });
162	  return { results };
163	};
