// What the scenario has accumulated before the current step: the results so far,
// plus the history a quote is priced against. Later steps (claims) will extend
// this accumulator rather than add a second counter beside it.
type ScenarioState = { results: Result[]; precedingQuotes: number };

const INITIAL_SCENARIO_STATE: ScenarioState = { results: [], precedingQuotes: 0 };

const afterStep = (
  state: ScenarioState,
  step: Step,
  customer: Customer,
): ScenarioState => {
  if (step.op !== "quote") throw new Error(`unsupported step: ${step.op}`);
  return {
    results: [
      ...state.results,
      quoteFor(step.items, { customer, precedingQuotes: state.precedingQuotes }),
    ],
    precedingQuotes: state.precedingQuotes + 1,
  };
};

export const runScenario = (scenario: Scenario): { results: Result[] } => {
  const { results } = scenario.steps.reduce(
    (state, step) => afterStep(state, step, scenario.customer),
    INITIAL_SCENARIO_STATE,
  );
  return { results };
};
